def asset(path,width=1450):
 im=Image.open(path).convert('RGB');im.thumbnail((width,1800));buf=io.BytesIO();im.save(buf,'JPEG',quality=86,optimize=True);return 'data:image/jpeg;base64,'+base64.b64encode(buf.getvalue()).decode()
def fig(path,title,text='',width=1450):return '<figure><img loading="lazy" src="'+asset(path,width)+'" alt="'+html.escape(title)+'"><figcaption><strong>'+html.escape(title)+'</strong>'+(' · '+html.escape(text) if text else '')+'</figcaption></figure>'
def shot(name,title,text='同一最终NBT的局部显示范围裁切；非游戏截图'):return fig(P/(name+'.png'),title,text)
def two(*items):return '<div class="two">'+''.join(items)+'</div>'
def section(num,title,content):return f'<section id="s{num}"><div class="kicker">{num:02d} / HIYORI OLD TOWN</div><h2>{title}</h2>{content}</section>'
def table(headers,rows):return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+html.escape(str(x))+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+html.escape(str(x))+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
