hero='<header><div class="eyebrow">HAF 0.4 · JAPAN DETAIL STUDY → TOWN BUILD</div><h1>日和旧街<span>十八栋，挤出一条有生活的老街。</span></h1><p>按“18栋、密集一点”重新排镇。窄面店宅连成北巷，主街留下较宽的旅馆与钱汤；统一木构灰瓦，再用门口陈设、檐口层次和室内用途拉开差别。</p><div class="badges"><b>18 栋 / 30 个楼层</b><b>6 家不同店铺</b><b>Java 1.21.1</b><b>'+RUN+'</b></div>'+shot('overview','18栋整体鸟瞰','读取最终NBT生成的简化离线预览；非Minecraft实机截图')+'</header>'
contents=[]
contents.append(section(1,'加密，仍然留出能走的巷道',two(fig(C/'review/previews/J09/overview.png','上一版 J09 · 12栋','保留为历史对照'),shot('top_day','本版 · 18栋真俯视','垂直正交相机；完整场地，无局部范围裁切'))+table(['比较项','J09','本版 '+RUN],[('栋数','12','18（增加50%）'),('场地','160 × 128','160 × 128，未扩大'),('建筑墙体占地',f'{oldarea:,} 格²',f'{newarea:,} 格²'),('墙体覆盖率',f'{oldarea/20480*100:.1f}%',f'{coverage:.1f}%（不含屋檐、道路、雨棚）'),('功能','7住宅、2商业、3公共','8住宅、6商业、4公共/服务'),('组织','两侧大体量为主','北巷连续8栋 + 主街北侧6栋 + 主街南侧4栋')])+'<p>北巷沿固定窄地块排布，前后退距略有错动。主街仍是7格沥青路，支巷3格；入口路径通常3格，双扇门与楼梯2格。店前不平均塞满，柜台、长凳和盆栽让开入户线。</p>'))
contents.append(section(2,'18栋索引与布局','<div class="two"><div class="map">'+plan+'</div><div><h3>8栋住宅 · 6家店 · 4处服务</h3><p>六家店是和菓子铺、味噌店、茶屋、小食堂、文具店和米店。旅馆、钱汤、町会所、小祠补齐公共与服务用途。公交亭、井台、公告栏、木桥不计入18栋。</p><h3>三个空间节奏</h3><p>北巷以窄店宅为主；主街用较完整的店面与旅馆组成街景；南侧用钱汤、住家、会所围出井台空隙。树木集中在边缘与后侧，水渠沿东边连接三座小桥。</p><p>点地图编号可跳到该栋。下面的筛选同时高亮地图和清单。</p><div class="filters"><button data-filter="all">全部18栋</button><button data-filter="home">住宅</button><button data-filter="shop">店铺</button><button data-filter="public">公共与服务</button></div></div></div>'))
cards=[]
for h in sp['buildings']:
 cat='home' if h['use']=='home' else 'shop' if h['use'] in ['sweets','miso','tea','tavern','stationery','rice'] else 'public'
 cards.append(f'<article id="b-{h["id"]}" class="bcard {cat}"><div class="kicker">{h["id"]} / {uses[h["use"]]}</div><h3>{h["name"]}</h3><p>{programs[h["use"]]}</p><small>{h["floors"]}层 · {h["w"]}×{h["d"]}格 · 地坪Y={h["g"]} · 檐深{h["eave_depth"]}格</small></article>')
