contents.append(section(3,'近看屋檐，再看店门排布',shot('walk','走进主街','完整模型透视视角；眼高在街面上方约3格')+two(shot('eave_detail','和菓子铺 · 仰看檐下','局部显示范围裁切：瓦边、深色檐板、外露椽端、窗台、暖帘与柜台'),shot('sweet_front','和菓子铺 · 立面层次'))+shot('shops','和菓子铺 → 味噌店 → 茶屋','三店局部裁切；屋脊方向、低侧翼和店前陈设有差别')+table(['研究线索','在本版中的表达','精度边界'],[('Freedom #104 檐底','瓦面 / 深色边板 / 间隔椽端 / 柱梁与撑木分别放置','用楼梯与半砖近似，没有复刻教程每一方块'),('窗与立面','窗后退一格，窗台与窗头外凸；稀竖格、边屏和木框三类','白色玻璃片模拟障子感，仍会透光，非真实纸门'),('门口排版','招牌板在上、暖帘在中、柜台在后、长凳与盆栽靠边','招牌为无字板；商品小件是彩色未点燃蜡烛的装饰代理'),('旅馆门厅','中央入户、两侧窗格、蓝帘与檐灯','原创比例，并非作者存档复刻'),('钱汤与小祠','钱汤前置小山墙雨棚，小祠使用低体量和供物空间','钱汤仅作直折山墙，尚未实现唐破风曲线')])+'<p class="note">本次使用已完成的 JapanDetail01 采样研究。没有把系列目录、无法播放的视频或未下载的百度存档说成已经学习完毕。内饰和空间是根据用途原创设计。</p>'))
contents.append(section(4,'特殊建筑与内饰积累',two(shot('inn_front','灯坂旅馆 · 门厅'),shot('inn_cut','旅馆首层 · 接待与水景角','局部横向剖切，移去上部以观察真实NBT家具和水池'))+two(shot('inn_upper','旅馆二层 · 客房与走廊','局部横向剖切；玻璃屏风仅作空间分隔近似'),shot('bath_cut','钱汤 · 接待、更衣、双池','局部横向剖切；水池围合已检查，实机流体待验'))+two(shot('sweet_cut','和菓子铺 · 前柜台与后席','局部横向剖切；装饰商品、储架、楼梯独立分层'),shot('paper_cut','文具店 · 书架与工作台','局部横向剖切；家具为原版方块组合'))+two(shot('H01_cut','住宅首层 · 玄关与生活区','局部横向剖切'),shot('H01_upper','住宅二层 · 榻榻米与铺床','局部横向剖切；地毯床铺不可交互睡眠'))+two(shot('bath_front','日和汤 · 对称入口与门前小屋顶'),shot('shrine_front','巷尾小祠 · 低体量的公共节点'))+'<p>建筑已经有不同的内部布置；厨卫管线、可睡眠床、门扇交互细化与全部房间的实机走查还没完成。当前以可进入的建筑骨架和用途陈设为目标。</p>'))
contents.append(section(5,'随机性：受位置和用途约束',shot('north_lane','北巷八栋 · 平屋、店宅、低侧翼交替','局部范围裁切；位置沿固定规划带，未声称任意seed自动布局')+table(['层级','本版实际执行','约束 / 尚未实现'],[('街道与配额','18个地块，8住宅/6店/4公共服务；3条道路','固定空间骨架，尚非自由地块求解器'),('地块变化','主街x偏移0–1格、宽度变化0–1格，z退距±1格','北排锁定横向宽度与位置，保证密集屋檐不互穿'),('屋顶与体量','平行/垂直屋脊、四坡、低侧翼、旅馆上层后退','体量家族由规划指定；不是随机拼屋顶'),('立面','每栋稳定ID选择木柱色、开间4/5格、三类窗格、住宅檐深2/3格','用途决定暖帘色和店前陈设；不逐方块乱换材质'),('瓦面与植物','少量瓦面材料差异、树高/树冠边缘、灌木与作物变化','种植避开地块和路线；未做真实年代劣化模拟'),('灯光','30个使用楼层都设灯；入口、檐下、候车与巷道另设灯','灯具位置按功能，不能靠随机熄灯制造疏密')])+'<p>种子 <code>'+str(spec['design_brief']['seed'])+'</code>。随机通道按布局、立面、屋顶、树木、灌木和作物拆分；同种子复跑的NBT字节完全一致。<code>age</code>、<code>maintenance</code>目前只是记录字段，未用于生成旧化，不能算已实现能力。</p>'))
contents.append(section(6,'夜景与完整四向',shot('walk_night','主街夜景','同机位、实际灯具位置的离线近似照明；不是游戏亮度验收')+'<details><summary>展开四向等尺度日夜图与真俯视</summary>'+two(*[shot(f+'_day',lab+' · 日景','完整模型，等尺度45°斜视') for f,lab in [('se','东南'),('sw','西南'),('ne','东北'),('nw','西北')]])+two(*[shot(f+'_night',lab+' · 夜景','完整模型，与日景同机位') for f,lab in [('se','东南'),('sw','西南'),('ne','东北'),('nw','西北')]])+'</details><p>门口和檐下是暖光，瓦面保留暗部，整条街不做均匀泛光。离线渲染使用简化方块模型与材质色；木纹、玻璃透明度、蜡烛和旗帜外观以原版游戏实际结果为准。</p>'))
contents.append(section(7,'同一模型的平面、剖面、立面与爆炸图',two(fig(D/'floor_1.png','18栋首层切层图','按每栋各自地坪取样；橙线是入户路径'),fig(D/'floor_2.png','二层切层图','12栋两层建筑；6栋平屋在此留空'))+two(fig(D/'section.png','H01 穿楼梯剖面','真实NBT格位，检查层高与楼板开口'),fig(C/'review/previews'/f'{RUN}_exploded'/'exploded.png','H01 分层爆炸','仅为展示加竖向间距；不可当作建造NBT'))+'<details><summary>H01四向立面样板</summary>'+two(*[fig(D/f'elevation_{f}.png','H01 '+lab+'立面') for f,lab in [('south','南'),('east','东'),('north','北'),('west','西')]])+'</details><p>详细剖面、四向立面和爆炸图只覆盖H01样板；整镇另外提供18栋布局、全部楼层切图和空间数据。18份HAF 0.4交接计划中，旅馆/钱汤/小祠暂映射到既有home/civic大类；具体用途和实际几何记录在本案例空间参数中。</p>'))
contents.append(section(8,'检查与交付状态',table(['检查','结果','范围'],[('最终NBT独立回读','通过',f'{mf["non_air_blocks"]:,}个非空气方块，位置与方块状态一致'),('几何规则','通过',f'{len(vf["checks"])}项：18栋配额、占地不重叠、入口、楼梯与落脚点、路径、车道、水体、灯具与旗帜支撑等'),('同种子复跑','通过','最终NBT字节哈希完全一致'),('世界区域文件回读','通过',f'{wc["checked_cells"]:,}个格位（含空气），0差异'),('暖帘方块实体','通过',f'{bc["world_banner_count"]}面原版旗帜，位置和纯色patterns独立核对一致'),('视觉复核','已检查','总览、店面与檐底、二层、夜景、北巷、技术图'),('Minecraft客户端','待验','没有运行游戏；碰撞、流体更新、光照与交互仍须实机验证')])+'<details><summary>几何检查明细与NBT哈希</summary><code class="hash">'+mf['sha256']+'</code><pre>'+html.escape(json.dumps(vf,ensure_ascii=False,indent=2))+'</pre></details>'))
contents.append(section(9,'历代变化与复用流程',table(['版本 / 分支','变化与状态'],[('J01–J05 / 现代小镇','12栋道路小镇，庭院与阳台；用户反馈过于现代，作为风格对照保留'),('J06–J09 / 老街初版','木构、灰瓦、暖帘；远看方向成立，近看檐口、店面和内饰仍需研究'),('JapanDetail01 / 专题研究','Freedom #104店铺、#101旅馆的10个采样观察；另有现实建筑补充与待看案例目录'),('J10 / 12栋重制草稿','将专题研究落到檐底、店前与用途内饰；随后用户要求18栋'),('J11 / 18栋加密','北排补6栋；检查发现钱汤池边被通道切开及一个两格台阶'),('J12 / 通道修正','修池边与入口高差；继续检查上层通行'),('J13 / 楼梯细查','修旅馆楼梯落脚和上层横向连通'),('J14 / 本次交付','将商品小物直接落在柜台上，补齐花盆承托；完成17项几何检查、回读、日夜预览与存档')])+'<p><b>现行流程：</b>读取当前案例与反馈 → 提取构件证据 → 定用途、空间和路线 → 规划地块 → 生成结构与用途细节 → NBT回读和几何检查 → 日夜及剖切复核 → 存档导出 → 实机与用户风格验收。</p><p><b>沿用Skills：</b><code>gafacraft-ha-research</code>管理证据；<code>gafacraft-concept-design</code>组织原创空间；<code>gafacraft-architect</code>串起建造、回读与交付。外部建筑AI资料包仍由<code>gafacraft-building-reference</code>负责。本次没有新装Skill，也没有训练模型权重。</p><p>HAF 0.4仍是工程主线；HAF05是研究整合编号；J14是本案例运行编号。原项目文件名前缀沿用JapanTown12以保留版本身份，内容已经是18栋。</p>'))
contents.append(section(10,'打开存档，然后看什么','<ol><li>解压世界ZIP，把里面的 <code>HiyoriTown18</code> 文件夹放入Minecraft的 <code>saves</code>。</li><li>用Java <b>1.21.1</b>打开。默认创造模式，出生点 <code>-74 65 4</code>，位于主街西端。</li><li>白天 <code>/time set day</code>，夜景 <code>/time set night</code>；首次加载让游戏重算光照。</li></ol><p>使用原版方块，无需模组。随机刻、天气、昼夜循环默认关闭；可按需开启。工程包包含生成器、最终NBT、历代输出、研究HTML与检查记录，保留后续可改性。</p><h3>下一轮优先研究</h3><ol><li><b>先实机走一圈：</b>从门口进入、上二楼，确认旗帜、梯口、水池和夜间照度，再记录近景风格反馈。</li><li><b>做真正不同的门面家族：</b>转角门面、折叠板窗、格子户、出格子、招牌文字；优先减少同一套开间重复。</li><li><b>扩充特殊建筑：</b>细化钱汤唐破风、小旅馆独立客房、店主起居与后勤，补可交互家具和厨卫。</li><li><b>再研究布局随机：</b>固定18栋功能配额，比较三套候选地块与巷道布局，检查檐口距离、通行和公共节点分布。</li></ol>'))
short='原创老式日式小镇，18栋密集木构街区，8住宅、6店铺、旅馆、钱汤、町会所、小祠；灰瓦深檐、外露椽端、退进窗框、暖帘、层次化店前陈设，功能内饰，窄巷、沥青路、木公交亭和水渠。'
long=short+' 160×128格；主街7格、支巷3格，北排8栋固定紧凑地块。屋顶朝向、单层/两层、侧翼和上层后退形成体量差异。白玻璃片为障子近似，地毯为装饰铺床；每个使用楼层有支撑的灯具。随机选择按楼栋ID和布局、立面、屋顶、植被通道隔离；不采用逐方块噪声，不随机熄灭功能灯。保持入口、楼梯、车道、水池边界，使用原版1.21.1方块。'
contents.append('<section><h2>研究来源与参数</h2><p>设计依据为附件 JapanDetail01 中已记录的采样观察；本轮的18栋空间方案和方块实现为原创。</p><ul><li><a href="https://chatgpt.com/library?file_id=libfile_2c3dc7148fc08191830a1a59e6b2d050&account_id=personal">JapanDetail01 · 屋檐、店面、特殊建筑与内饰研究</a></li><li><a href="https://www.youtube.com/watch?v=I40jEm-xIsU">Freedom #104 · 店铺原始视频</a></li><li><a href="https://www.youtube.com/watch?v=QRdePpYnhBw">Freedom #101 · 旅馆原始视频</a></li><li><a href="https://chatgpt.com/library?file_id=libfile_663d4d014de08191a97fdef972408368&account_id=personal">JapanTown01 · 早期风格研究与系列目录</a></li></ul><button id="saveSpec">下载18栋空间参数 JSON</button><details><summary>长短设计关键词</summary><p>'+short+'</p><p>'+long+'</p></details></section>')
