js='''document.getElementById('saveSpec').onclick=()=>{const u=URL.createObjectURL(new Blob([document.getElementById('case-data').textContent],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='JapanTown18_Design.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{const f=b.dataset.filter;document.querySelectorAll('.bcard').forEach(c=>c.hidden=f!=='all'&&!c.classList.contains(f));document.querySelectorAll('.lot').forEach(c=>c.style.opacity=f==='all'||c.classList.contains(f)?'1':'.2')});const dlg=document.getElementById('zoom');document.querySelectorAll('figure img').forEach(im=>im.onclick=()=>{document.getElementById('zoomimg').src=im.src;document.getElementById('zoomimg').alt=im.alt;dlg.showModal()});document.getElementById('closezoom').onclick=()=>dlg.close();dlg.addEventListener('click',e=>{if(e.target===dlg)dlg.close()});'''
